var a=`0168-tagliatelle-al-ragu`;var i=`world-0168`;var n=`IT`;var o=`southern-europe`;var r=4;var l=146;var s={en:`Tagliatelle al Ragù`,ua:`Тальятеле з рагу`};var g={en:`A classic dish from Italy, featuring ground beef, ground pork, yellow onion, carrot. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: яловичий фарш, свинячий фарш, жовта цибуля, морква. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`ground-beef`,370,`g`],[`ground-pork`,230,`g`],[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,130,`g`],[`carrot`,120,`g`],[`celery-stalk`,100,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 110 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 110 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:110,i:[[`tomato-passata`,450,`g`],[`whole-cow-milk`,140,`ml`],[`dry-white-wine`,150,`ml`],[`bay-leaf`,1,`leaf`]]},{en:`Cook the pasta in generously salted boiling water for about 9 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 9 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:9,i:[[`tagliatelle`,400,`g`],[`water`,1600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parmigiano-reggiano`,70,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:a,id:i,country:`IT`,region:o,servings:4,minutes:146,title:s,text:g,steps:u};export{n as country,d as default,i as id,l as minutes,o as region,r as servings,a as slug,u as steps,g as text,s as title};